import { fileURLToPath, pathToFileURL } from "node:url";
import { createRequire } from "node:module";
import { build } from "vite";

const root = path.resolve("filefn/docs");
const configUrl = pathToFileURL(path.join(root, "vite.config.ts")).href;
const { default: userConfig } = await import(configUrl);
const config = typeof userConfig === "function" ? await userConfig({ command: "build", mode: "production" }) : userConfig;

